#!/usr/bin/env python3
"""Create hand-optimized Micronucleus all-AVR-assembly. Based on byte-exact original reconstruction.
   Changes restricted to non-VUSB routines; see CHANGES.md.
"""
from pathlib import Path
import re,sys
SRC=Path(__file__).parent/'original_decoded.S'
KEEP_LED='--keep-led' in sys.argv
OUT=Path(__file__).parent/('optimized_led_on.S' if KEEP_LED else 'optimized.S')
s=SRC.read_text()
# set link-time absolute bootloader address before .org, later regenerated by -D BOOT_AT=...
s=s.replace('.org 0x1a40', '''/* Edit BOOT_AT only after the build audits that the loader fits in flash. */
#ifndef BOOT_AT
#define BOOT_AT 0x1ac0
#endif
.org BOOT_AT''')
s=s.replace('    .byte 0x1a, 0x3c, 0x40, 0x05, 0x93, 0x11, 0x00, 0x00  /* 1a42 */',
'''    .byte ((BOOT_AT - 4) >> 8), ((BOOT_AT - 4) & 0xff), 0x40, 0x05, 0x93, 0x11, 0x00, 0x00  /* device config: user flash, page, write delay, signature */''')
# direct patches before symbolic address use: original assembler each instruction comment address
# Remove LED from GPIO and loop.  No edits to USB_handler/CRC at addresses 1ab8..1ccc.
skip={0x1a7a,0x1a80,0x1a86}
if not KEEP_LED:
    skip.update({0x1d30,0x1e7c,0x1e7e,0x1e80,0x1e82,0x1eac,0x1f82,0x1f84})
# NOTE removal of rjmp 1a80 is covered by natural fallthrough from ldi r27 at 1a7e
# Loop cpi r26,0x2c still compares correct after each store, 44-byte .bss init no 16-bit compare needed
# Base Y used for compact LDD/STD *after* the polling loop: replace only addresses > 1d9c
# Y was 5ms counter in poll, and is reset next poll at 1d3a. When command dispatch starts, Y is free.
# r23 used instead of r28 to hold transmit length in the frame build, preserving Y.
changes={
0x1e0c:('mov','r23, r24'),0x1e12:('ldi','r23, 0x08'),0x1e16:('sub','r25, r23'),
0x1e38:('mov','r24, r23'),0x1e4c:('mov','r22, r23'),0x1e54:('subi','r23, 0xfc'),
0x1e56:('cpi','r23, 0x0c'),
0x1e60:('std','Y+15, r23'),
0x1cd4:('ldi','r24, ((0xc000 + (BOOT_AT / 2) - 1) & 0xff)'),
0x1cd6:('ldi','r25, ((0xc000 + (BOOT_AT / 2) - 1) >> 8)'),
0x1d66:('ldi','r30, (BOOT_AT & 0xff)'),0x1d68:('ldi','r31, (BOOT_AT >> 8)'),
0x1d8a:('cpi','r30, (BOOT_AT & 0xff)'),0x1d8c:('ldi','r24, (BOOT_AT >> 8)'),
0x1dd4:('ldi','r24, ((BOOT_AT + 2) & 0xff)'),0x1dd6:('ldi','r25, ((BOOT_AT + 2) >> 8)'),
0x1e72:('ldi','r30, ((BOOT_AT - 3) & 0xff)'),0x1e74:('ldi','r31, ((BOOT_AT - 3) >> 8)'),
0x1f46:('ldi','r24, ((BOOT_AT + 0x1c) & 0xff)'),0x1f48:('ldi','r25, ((BOOT_AT + 0x1c) >> 8)'),
0x1f5c:('ldi','r24, ((BOOT_AT + 0x0a) & 0xff)'),0x1f5e:('ldi','r25, ((BOOT_AT + 0x0a) >> 8)'),
0x1ebe:('.word','(0xc000 | (((bootloader_start - 4 - app_jump - 2)/2) & 0x0fff))'),
}
# Build modifications and keep annotation originals in-line
lines=[]
for line in s.splitlines():
    if '.word 0xcdbe' in line:
        lines.append('app_jump:')
        lines.append('    .word (0xc000 | (((bootloader_start - 4 - app_jump - 2)/2) & 0x0fff)) /* relative RJMP into application postscript */')
        continue
    match=re.search(r'/\* 0x([0-9a-f]+):\s*([0-9a-f ]+) \*/',line)
    if not match:lines.append(line);continue
    addr=int(match.group(1),16)
    if addr in skip:
        lines.append(f'    /* Removed 0x{addr:04x}: '+line.strip().split('/*')[0].strip()+' (size-optimized, see CHANGES.md) */')
        continue
    if addr == 0x1d9c:
        lines.append('    /* Y=0x0100 is a base pointer for usbdrv SRAM globals during command/packet handling. */')
        lines.append('    ldi     r28, 0x00')
        lines.append('    ldi     r29, 0x01')
    if addr in changes:
        op,operand=changes[addr]
        if addr==0x1ebe:lines.append('app_jump:')
        line=f'    {op:7s} {operand:43s} /* original at 0x{addr:04x} */'
    # all LDS/STS data in this lifetime compact to LDD/STD (Y+offset)
    elif addr>=0x1d9c and line.lstrip().startswith(('lds ','sts ')):
        m=re.match(r'^\s*(lds|sts)\s+(r\d+|0x[0-9a-f]+),\s*(r\d+|0x[0-9a-f]+)',line)
        if m:
            op,arg1,arg2=m.groups()
            if op=='lds':
                reg,mem=arg1,int(arg2,16)
                if 0x100<=mem<0x140:
                    line=f'    ldd     {reg}, Y+{mem-0x100}   /* {addr:04x}: SRAM compact access */'
            else:
                mem,reg=int(arg1,16),arg2
                if 0x100<=mem<0x140:
                    line=f'    std     Y+{mem-0x100}, {reg}   /* {addr:04x}: SRAM compact access */'
    lines.append(line)
OUT.write_text('\n'.join(lines)+'\n')
print('created',OUT,'del instr',len(skip),'replaced',len(changes))
